fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo, find and open the Integrations application, and open its 'Schedules' section. On a schedule card, ensure the 'Auto-sync' toggle is on so the schedule config controls are visible, then click the 'Interval' type pill and confirm interval preset buttons (e.g. 15m/hourly) plus a custom-minutes input appear. Then click the 'Cron' type pill and confirm cron preset buttons and a cron expression input appear, with a human-readable cron description shown when an expression is set. Note that changing config surfaces a 'Save' button on the card. You do NOT need to click Save. Seeing the schedule-type pills switch the config UI reactively is success. If no schedules exist, the 'No integrations found' empty state is acceptable. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
